    20→/** Get the current user ID, works in both foreground and background */
    21→const getCurrentUserId = (): string | null => {
    22→  // Try to get from active instance first (foreground)
    23→  const instanceUserId = MatrixService.instance?.userId();
    24→  if (instanceUserId) return instanceUserId;
    25→
    26→  // Fall back to stored credentials (works in background)
    27→  const credentials = MatrixStorage.getLoginCredentials();
    28→  return credentials?.userId || null;
    29→};
    30→
    31→/**
    32→ * Ensure MatrixService is initialized for background decryption
    33→ * Uses lightweight initialization that doesn't start sync service
    34→ */
    35→const ensureServiceInitialized = async (): Promise<boolean> => {
    36→  const notificationClient = MatrixService.getNotificationClient();
    37→  if (notificationClient) return true;
    38→
    39→  // Foreground: create notification client if possible
    40→  if (MatrixService.instance) {
    41→    const client = await MatrixService.ensureNotificationClient();
    42→    return !!client;
    43→  }
    44→
    45→  // Try to restore session with lightweight background method
    46→  try {
    47→    const restored = await MatrixService.restoreSessionForBackground();
    48→    return restored;
    49→  } catch (error) {
    50→    console.error("[Push] Failed to restore session:", error);
    51→    return false;
    52→  }
    53→};
